            is FfiStoreException.ChallengeIssuanceNotFound -> {
                buf.putInt(8)
                Unit
            }
            is FfiStoreException.Cancelled -> {
                buf.putInt(9)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




